/** Architecture hygiene plus independent rendered visual verification. */
class Design_Core_Elementor_Visual_QA{const VERSION=2;public function audit_page($page_id,array $context=array()){$raw=get_post_meta($page_id,'_elementor_data',true);if(!$raw)return $this->fail($page_id,'No Elementor data found.');$elements=is_array($raw)?$raw:json_decode($raw,true);if(!is_array($elements))return $this->fail($page_id,'Invalid Elementor JSON.');$flat=$this->flatten($elements);$issues=array();$rec=array();$penalty=0;$arch=class_exists('Design_Core_Elementor_Architecture_Auditor')?(new Design_Core_Elementor_Architecture_Auditor())->audit($elements):array();if(!empty($arch['stylesheet_html_widget_count'])){$issues[]=array('type'=>'critical','message'=>$arch['stylesheet_html_widget_count'].' HTML widget(s) control Elementor outside their ownership.');$penalty+=35;}if(!empty($arch['class_only_container_count'])){$issues[]=array('type'=>'warning','message'=>$arch['class_only_container_count'].' class-only container(s) have no native style controls.');$penalty+=min(20,$arch['class_only_container_count']);}if(!empty($arch['important_declaration_count'])){$issues[]=array('type'=>'warning','message'=>$arch['important_declaration_count'].' !important declaration(s) reduce editor control ownership.');$penalty+=min(10,$arch['important_declaration_count']);}$ids=array_filter(array_column($flat,'id'));if(count($ids)!==count(array_unique($ids))){$issues[]=array('type'=>'critical','message'=>'Duplicate Elementor element IDs detected.');$penalty+=40;}$colors=$fonts=array();$missing_alt=$responsive=$globals=$html=0;foreach($flat as $e){$s=(array)($e['settings']??array());if('html'===($e['widgetType']??''))$html++;if(!empty($s['__globals__'])&&is_array($s['__globals__']))$globals+=count($s['__globals__']);foreach($s as $k=>$v){if(false!==strpos($k,'color')&&is_string($v)&&$v)$colors[]=$v;if(false!==strpos($k,'font_family')&&is_string($v)&&$v)$fonts[]=$v;if(preg_match('/_(tablet|mobile|mobile_extra|tablet_extra|laptop)$/',$k))$responsive++;}if('image'===($e['widgetType']??'')&&empty($s['image']['alt'])&&empty($s['alt']))$missing_alt++;}$thresholds=class_exists('Design_Core_Elementor_Settings')?Design_Core_Elementor_Settings::get_qa_thresholds():array();if(count(array_unique($colors))>max(1,(int)($thresholds['color_limit']??8))){$issues[]=array('type'=>'warning','message'=>'Color count exceeds design-system limit.');$penalty+=8;}if(count(array_unique($fonts))>max(1,(int)($thresholds['font_limit']??3))){$issues[]=array('type'=>'warning','message'=>'Font count exceeds design-system limit.');$penalty+=5;}if($missing_alt){$issues[]=array('type'=>'warning','message'=>$missing_alt.' image(s) may be missing alt text.');$penalty+=min(10,$missing_alt*2);}if($html){$issues[]=array('type'=>'warning','message'=>$html.' raw HTML widget(s) require architecture justification.');$penalty+=min(20,$html*5);}if(!$responsive)$rec[]='No responsive overrides detected; rendered multi-viewport QA is required.';if(!$globals)$rec[]='No global references detected; verify token synchronization.';$widgets=count(array_filter($flat,static fn($e)=>'widget'===($e['elType']??'')));$depth=$this->depth($elements);if($depth>8){$issues[]=array('type'=>'warning','message'=>'Deep nesting detected ('.$depth.').');$penalty+=5;}$score=(float)max(0,100-$penalty);$critical=count(array_filter($issues,static fn($x)=>'critical'===($x['type']??'')));$status=$critical||$score<(float)($thresholds['min_score']??85)?'fail':($issues?'warning':'pass');$ux=class_exists('Design_Core_Elementor_UX_Quality_Auditor')?(new Design_Core_Elementor_UX_Quality_Auditor())->audit_page((int)$page_id):array('status'=>'unavailable');$visual=array('status'=>!empty($context['reference_target'])?'unverified':'not-applicable');if(!empty($context['reference_target'])&&!empty($context['candidate_target'])){$visual=$this->compare_targets($context['reference_target'],$context['candidate_target'],array('page_id'=>(int)$page_id,'target_similarity'=>(float)($context['target_similarity']??.95)));if(is_wp_error($visual))$visual=array('status'=>'unavailable','error'=>$visual->get_error_message());}$responsive_state=!$responsive?'unverified':'pass';if(!empty($visual['analysis_used']))$responsive_state='pass'===($visual['status']??'')?'pass':'fail';$gate=class_exists('Design_Core_Elementor_Visual_Quality_Gate')?(new Design_Core_Elementor_Visual_Quality_Gate())->evaluate(array('architecture'=>array('status'=>in_array($status,array('pass','warning'),true)?'pass':'fail','score'=>$score),'responsive'=>array('status'=>$responsive_state,'score'=>$responsive?100:null),'visual'=>$visual,'interaction'=>(array)($context['interaction']??array('status'=>!empty($context['interactive'])?'unverified':'not-applicable')),'ux'=>$ux),array('reference_exists'=>!empty($context['reference_target']),'interactive'=>!empty($context['interactive']))):array('status'=>'unavailable','publishable'=>false);return array('version'=>2,'page_id'=>(int)$page_id,'status'=>$status,'score'=>$score,'issues'=>$issues,'recommendations'=>$rec,'performance'=>array('widget_count'=>$widgets,'nesting_depth'=>$depth),'responsive_override_count'=>$responsive,'global_reference_count'=>$globals,'raw_html_widget_count'=>$html,'architecture'=>$arch,'ux_quality'=>$ux,'visual'=>$visual,'quality_gate'=>$gate);}
public function compare_targets($reference_target,$candidate_target,array $context=array()){if(!class_exists('Design_Core_Elementor_Visual_Feedback_Engine'))return new WP_Error('design_core_visual_feedback_unavailable','Rendered visual feedback engine is unavailable.');return(new Design_Core_Elementor_Visual_Feedback_Engine())->evaluate_targets($reference_target,$candidate_target,$context);}private function fail($id,$m){return array('version'=>2,'page_id'=>(int)$id,'status'=>'fail','score'=>0,'issues'=>array(array('type'=>'critical','message'=>$m)),'recommendations'=>array(),'performance'=>array(),'visual'=>array('status'=>'unverified'),'quality_gate'=>array('status'=>'blocked','publishable'=>false));}private function flatten($e){$o=array();foreach($e as $x){$o[]=$x;if(!empty($x['elements']))$o=array_merge($o,$this->flatten($x['elements']));}return $o;}private function depth($e,$d=0){$m=$d;foreach($e as $x)if(!empty($x['elements']))$m=max($m,$this->depth($x['elements'],$d+1));return $m;}}
